import { createEffect, createMemo, createSignal, For, on, onCleanup, onMount, Show, useContext } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { Activatable } from "#core/ui-next/components/activatable.jsx";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CheckBox } from "#core/ui-next/components/check-box.jsx";
import { Dropdown, DropdownItem } from "#core/ui-next/components/dropdown.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SearchBar } from "#core/ui-next/components/search-bar.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-nested.jsx";
import { AgeSelectModel, AgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import { CivCard } from "#core/ui-next/screens/create-game/civ-card.jsx";
import { CivDetailsBase } from "#core/ui-next/screens/create-game/civ-details.jsx";
import { CivInfo, CivSelectModel, CivSelectModelContext } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { CreateGameHRule } from "#core/ui-next/screens/create-game/create-game-components.jsx";
import { CivUnlocksModel } from "#core/ui-next/screens/unlocks/civ-unlocks-model.js";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { HotkeyContext } from "#core/ui-next/services/hotkey.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { ViewExperience } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import { useLegaciesScreenContext } from "#base/ui-next/screens/legacies/legacies-model.js";

import style from "#base/ui-next/screens/legacies/legacies-civ-unlocks-tab.scss?url";

interface AgeFilterItem {
	ageType?: string;
	ageName: string;
}

export const LegaciesUnlocksTabComponent = () => {
	const unlocksModel = CivUnlocksModel.get();
	const ageSelectModel = AgeSelectModel.get();
	const legaciesModel = useLegaciesScreenContext();

	const isSmallScreen = useIsSmallScreen();
	const isMobile = ViewExperience() == UIViewExperience.Mobile;

	const hotkeyContext = useContext(HotkeyContext);

	const attributeFilters = ["LOC_LEGACIES_FILTER_ALL_ATTRIBUTES"];
	Database.query(
		"config",
		"SELECT * FROM Tags WHERE TagCategoryType = 'TAG_CATEGORY_TRAIT' AND TagType IN (SELECT DISTINCT TagType FROM CivilizationTags)",
	)?.forEach((tag) => {
		if (tag.Name) attributeFilters.push(tag.Name as string);
	});

	const [textFilter, setTextFilter] = createSignal<string>("");
	const [shouldShowAllRequirements, setShouldShowAllRequirements] = createSignal<boolean>(false);
	const [attributeFilter, setAttributeFilter] = createSignal<string | undefined>(
		"LOC_LEGACIES_FILTER_ALL_ATTRIBUTES",
	);
	const [viewCiv, setViewCiv] = createSignal<CivInfo | undefined>();
	const initialSelectedCiv =
		unlocksModel.civInfo.find((civ) => civ.civID == unlocksModel.currentCivType) ?? unlocksModel.civInfo[0];
	const [selectedUnlocksCiv, setSelectedUnlocksCiv] = createSignal<CivInfo | undefined>(initialSelectedCiv);
	const civDetailsContextModel = {
		civs: unlocksModel.civInfo,
		randomCiv: unlocksModel.civInfo.find((c) => c.civID == "RANDOM") ?? unlocksModel.civInfo[0],
		previousCiv: () => undefined,
		selectedCiv: () => selectedUnlocksCiv() ?? unlocksModel.civInfo[0],
		setSelectedCiv: (civ: CivInfo) => setSelectedUnlocksCiv(civ),
		viewCiv,
		setViewCiv,
		selectNext: () => {
			const selected = selectedUnlocksCiv() ?? unlocksModel.civInfo[0];
			const index = unlocksModel.civInfo.findIndex((c) => c.civID == selected.civID);
			if (index < 0 || unlocksModel.civInfo.length == 0) {
				return;
			}

			const nextIndex = (index + 1) % unlocksModel.civInfo.length;
			setSelectedUnlocksCiv(unlocksModel.civInfo[nextIndex]);
		},
		selectPrev: () => {
			const selected = selectedUnlocksCiv() ?? unlocksModel.civInfo[0];
			const index = unlocksModel.civInfo.findIndex((c) => c.civID == selected.civID);
			if (index < 0 || unlocksModel.civInfo.length == 0) {
				return;
			}

			const prevIndex = (index - 1 + unlocksModel.civInfo.length) % unlocksModel.civInfo.length;
			setSelectedUnlocksCiv(unlocksModel.civInfo[prevIndex]);
		},
		fulltextSearch: (text: string) => {
			const normalized = text.trim().toLowerCase();
			if (!normalized) {
				return new Set(unlocksModel.civInfo.map((civ) => civ.civID));
			}

			return new Set(
				unlocksModel.civInfo.filter((civ) => civ.fulltext.includes(normalized)).map((civ) => civ.civID),
			);
		},
	} as CivSelectModel;

	const enableTextFilter = createMemo<boolean>(() => ViewExperience() == UIViewExperience.Desktop);

	const ageFilters: AgeFilterItem[] = Array.from(GameInfo.Ages).map((ageDef) => ({
		ageType: ageDef.AgeType,
		ageName: ageDef.Name,
	}));

	const audio = useAudio("LegaciesCiv");

	onMount(() => {
		audio("popup-open");
	});

	onCleanup(() => {
		hotkeyContext.unregisterNavtray("nav-shell-next");
		hotkeyContext.unregisterNavtray("shell-action-2");
		hotkeyContext.unregisterNavtray("shell-action-1");
	});

	// Clear navtray when opening civ details, restore when closing
	createEffect(
		on(
			() => legaciesModel.isShowingDetails(),
			(isShowing) => {
				if (isShowing) {
					hotkeyContext.unregisterNavtray("nav-shell-next");
					hotkeyContext.unregisterNavtray("shell-action-2");
					hotkeyContext.unregisterNavtray("shell-action-1");
				} else {
					hotkeyContext.registerNavtray("nav-shell-next", "LOC_UI_PLAYER_UNLOCKS_SHOW_ALL_REQUIREMENTS");
					hotkeyContext.registerNavtray("shell-action-1", "LOC_LEGACIES_FILTER_ATTRIBUTES");
					hotkeyContext.registerNavtray("shell-action-2", "LOC_LEGACIES_FILTER_AGES");
				}
			},
		),
	);

	ageFilters.unshift({ ageName: "LOC_UI_CREATE_GAME_FILTER_ALL_AGES" });

	let initialSelectedAge: AgeFilterItem = { ageName: "LOC_UI_CREATE_GAME_FILTER_ALL_AGES" };
	let nextAgeName = "";
	let hasNextAge = false;
	const ageSuccessor = GameInfo.AgeSuccessors.lookup(Game.age);
	if (ageSuccessor) {
		const nextAgeDef = GameInfo.Ages.find((a) => a.AgeType == ageSuccessor.SuccessorAgeType);
		if (nextAgeDef) {
			nextAgeName = nextAgeDef.Name;
			initialSelectedAge = { ageType: nextAgeDef.AgeType, ageName: nextAgeDef.Name };
			hasNextAge = true;
		}
	} else {
		const currentAgeDef = GameInfo.Ages.find((a) => a.$hash == Game.age);
		if (currentAgeDef) {
			nextAgeName = currentAgeDef.Name;
			initialSelectedAge = { ageType: currentAgeDef.AgeType, ageName: currentAgeDef.Name };
		}
	}
	const [selectedAgeFilter, setSelectedAgeFilter] = createSignal<AgeFilterItem>(initialSelectedAge);

	const normalizedText = createMemo(() => textFilter().trim().toLowerCase());

	const showSearch = createMemo(() => ViewExperience() == UIViewExperience.Desktop && !IsControllerActive());
	const selectedCivId = createMemo(() => selectedUnlocksCiv()?.civID ?? "");

    const hasUnlockRequirements = () =>
        filteredCivs().some((civInfo) => civInfo.unlockedBy?.length > 0
    );

	const filteredCivs = createMemo(() => {
		const selectedAge = selectedAgeFilter().ageType;
		const selectedAttribute = attributeFilter();
		const searchText = normalizedText();
		const shouldFilterText = enableTextFilter();
		const filtered = unlocksModel.civInfo.filter((civ) => {
			const matchAge = civ.apexAge == selectedAge || !selectedAge;
			const matchAttribute =
				selectedAttribute == "LOC_LEGACIES_FILTER_ALL_ATTRIBUTES" ||
				civ.traits.some((t) => t == selectedAttribute);
			const matchText = !shouldFilterText || civ.fulltext.includes(searchText);
			return matchAge && matchAttribute && matchText;
		});
		return filtered;
	});

	createEffect(() => {
		if (legaciesModel.isShowingDetails()) {
			setViewCiv(selectedUnlocksCiv());
		}
	});

	return (
		<>
			<NestedTooltipContext.Provider value={{ disabled: true }}>
				<AudioContextProvider segment="LegaciesCiv">
					<Show
						when={hasNextAge}
						fallback={
							<>
								<div
									class={`mt-2 flex flex-col flex-auto items-center justify-center ${isMobile ? "mx-5 px-5 pb-4" : "mx-8 px-8"} ${isMobile && IsControllerActive() ? "mb-13" : "mb-5"} pt-2 relative`}
									style={{
										"background-image":
											"linear-gradient(rgba(20, 20, 20, 0.8), rgba(20, 20, 20, 0.7), rgba(20, 20, 20, 0.8))",
									}}
								>
									<div
										class="absolute h-6 -top-0\.5 -left-1\.5 -right-1\.5"
										style={{
											"border-image-source": "url(blp:hud_section-line)",
											"border-image-slice": "4 32 0 32 fill",
											"border-image-width": "auto",
										}}
									/>
									<div class="text-xl uppercase font-title flex-wrap">
										<L10n.Compose text="LOC_LEGACIES_UNLOCKS_FINAL_AGE" />
									</div>
									<div
										class="absolute h-6 -bottom-0\.5 -left-1\.5 -right-1\.5 -scale-y-100"
										style={{
											"border-image-source": "url(blp:hud_section-line)",
											"border-image-slice": "4 32 0 32 fill",
											"border-image-width": "auto",
										}}
									/>
								</div>
							</>
						}
					>
						<AgeSelectModelContext.Provider value={ageSelectModel}>
							<div class={`w-full text-center text-accent-2 text-sm ${isMobile ? "px-4" : ""}`}>
								<L10n.Compose text="LOC_UI_PLAYER_UNLOCKS_COMPLETE_LISTED_REQUIREMENTS_CIVILIZATIONS" />
							</div>
							<div
								class={`mt-2 flex flex-col flex-auto items-center ${isMobile ? "mx-5 px-5 pb-4" : "mx-8 px-8"} ${isMobile && IsControllerActive() ? "mb-13" : "mb-5"} pt-2 relative`}
								style={{
									"background-image":
										"linear-gradient(rgba(20, 20, 20, 0.8), rgba(20, 20, 20, 0.7), rgba(20, 20, 20, 0.8))",
								}}
							>
								<Show when={!legaciesModel.isShowingDetails()}>
									<div
										class="absolute h-6 -top-0\.5 -left-1\.5 -right-1\.5"
										style={{
											"border-image-source": "url(blp:hud_section-line)",
											"border-image-slice": "4 32 0 32 fill",
											"border-image-width": "auto",
										}}
									/>
									<div class={`flex flex-row w-full mt-1\\.5 mb-2 relative`}>
										<Show when={showSearch()}>
											<SearchBar
												hotkeyAction="nav-shell-previous"
												value={textFilter}
												setValue={setTextFilter}
												class={`unlocks-search-bar mr-2 font-fit-shrink`}
											/>
										</Show>
										<div
											class={`items-end justify-end grow flex flex-row font-fit-shrink ${isSmallScreen() ? "text-xs" : "text-base"}`}
										>
											<div
												class={`flex flex-row ${
													isMobile
														? "self-center w-1\\/2 justify-start items-center -mt-2"
														: ""
												}`}
											>
                                                <Show when={hasUnlockRequirements()}>
                                                    <div class="uppercase mr-2">
                                                        <L10n.Compose text="LOC_UI_PLAYER_UNLOCKS_SHOW_ALL_REQUIREMENTS" />
                                                    </div>
                                                    <CheckBox
                                                        disableFocus={true}
                                                        class={`${isMobile ? "size-10" : "size-6"}`}
                                                        isChecked={shouldShowAllRequirements()}
                                                        hotkeyAction="nav-shell-next"
                                                        onActivate={() => {
                                                            setShouldShowAllRequirements((shouldShow) => !shouldShow);
                                                        }}
                                                    />
                                                </Show>
												<div
													class={`uppercase ${isSmallScreen() ? "ml-2 mr-2" : "ml-12 mr-6"}`}
												>
													<L10n.Compose
														text="LOC_LEGACIES_UNLOCKS_NUM_CIVS"
														args={[filteredCivs().length.toString()]}
													/>
												</div>
											</div>
											<div class={`flex flex-row ${isMobile ? "w-1\\/2 justify-end" : ""}`}>
												<Dropdown
													disableFocus={true}
													defaultValue={selectedAgeFilter()}
													selectedItemTemplate={(ageItem) => (
														<div
															class={`m-1 flex grow min-w-0 truncate font-fit-shrink ${isSmallScreen() ? "text-xs" : ""}`}
														>
															<L10n.Stylize
																text="LOC_UI_CREATE_GAME_FILTER_ITEM"
																args={[Locale.compose(ageItem.ageName)]}
															/>
														</div>
													)}
													hotkey="shell-action-2"
													onItemSelected={(ageItem) => {
														setSelectedAgeFilter(ageItem);
													}}
													class="mr-2 unlocks-filter font-fit-shrink"
												>
													<For each={ageFilters}>
														{(ageItem) => (
															<DropdownItem value={ageItem}>
																{Locale.compose(ageItem.ageName)}
															</DropdownItem>
														)}
													</For>
												</Dropdown>
												<Dropdown
													defaultValue={attributeFilter()}
													disableFocus={true}
													selectedItemTemplate={(item) => (
														<div
															class={`m-1 flex grow min-w-0 truncate font-fit-shrink ${isSmallScreen() ? "text-xs" : ""}`}
														>
															<L10n.Stylize
																text="LOC_UI_CREATE_GAME_FILTER_ITEM"
																args={[Locale.compose(item)]}
															/>
														</div>
													)}
													hotkey="shell-action-1"
													onItemSelected={(item) => {
														setAttributeFilter(item);
													}}
													class="unlocks-filter font-fit-shrink"
												>
													<For each={Object.values(attributeFilters)}>
														{(item) => (
															<DropdownItem value={item}>
																{Locale.toUpper(Locale.compose(item))}
															</DropdownItem>
														)}
													</For>
												</Dropdown>
											</div>
										</div>
									</div>
									<div class="flex-auto relative w-full flex flex-row">
										<div
											class={`flex flex-col items-center h-full w-84 ${isMobile ? "pr-10" : "px-10"}`}
										>
											<L10n.Stylize
												text={
													!hasNextAge
														? "LOC_LEGACIES_CURRENT_AGE"
														: "LOC_LEGACIES_UPCOMING_AGE"
												}
												class={`text-base uppercase font-title ${isMobile ? "whitespace-nowrap" : ""}`}
											/>
											<L10n.Stylize
												text={nextAgeName}
												class="font-title text-tertiary-1 font-black uppercase text-white text-xl mb-2"
											/>
											<div class="flex flex-col items-center relative civ-select-age-banner">
												<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
												<div
													class="absolute inset-0"
													style={{
														"background-image": `url('${ageSelectModel.selectedAge.bgImage}')`,
														"background-position": "center center",
														"background-size": "cover",
													}}
												/>
												<div class="create-game-hub-bottom-gradient absolute left-0 bottom-0" />
												<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />
												<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
												<div
													class="flex items-center justify-center size-36 relative m-4"
													style={{
														width: Layout.pixels(132),
														height: Layout.pixels(132),
														"background-image": "url(blp:hud_sub_circle_dis_128x128)",
														"background-repeat": "no-repeat",
														"background-size": "cover",
													}}
												>
													<Icon
														name={ageSelectModel.selectedAge.icon}
														class="size-24 -bottom-px relative"
														isUrl={true}
													/>
												</div>
											</div>
										</div>
										<ScrollArea class="flex-auto">
											<SpatialSlot name="civ-unlocks-scrollable">
												<div class="flex flex-row flex-wrap w-full">
													<For each={filteredCivs()}>
														{(civ) => (
															<Tab.Trigger name="civ-details">
																<AudioContextProvider segment="CivCard">
																	<CivCard
																		class="is-unlocks"
																		{...civ}
																		isSelected={civ.civID == selectedCivId()}
																		isApexAgeSelected={
																			ageSelectModel.nextAge.type == civ.apexAge
																		}
																		leaderIcon={unlocksModel.leaderIcon}
																		isRecommended={false}
																		isUnlocks={true}
																		showAllUnlocks={shouldShowAllRequirements()}
																		onSelect={() => {
																			setSelectedUnlocksCiv(civ);
																			setViewCiv(civ);
																			legaciesModel.setIsShowingDetails(true);
																		}}
																	/>
																</AudioContextProvider>
															</Tab.Trigger>
														)}
													</For>
												</div>
												<CreateGameHRule class="my-2" />
											</SpatialSlot>
										</ScrollArea>
									</div>
								</Show>
								<AudioContextProvider segment="LegaciesCivShowing">
									<Show when={legaciesModel.isShowingDetails()}>
										<CivSelectModelContext.Provider value={civDetailsContextModel}>
											<CivDetailsBase />
										</CivSelectModelContext.Provider>

										<Activatable
											class={`absolute ${isMobile ? "size-14 top-5 left-5" : "size-10 top-10 left-10"} bg-center bg-no-repeat bg-contain`}
											onActivate={() => {
												setViewCiv(undefined);
												legaciesModel.setIsShowingDetails(false);
											}}
											hotkeyAction="cancel"
											style={{ "background-image": "url(blp:shell_back-button-focus)" }}
										/>
									</Show>
								</AudioContextProvider>
								<div
									class="absolute h-6 -bottom-0\.5 -left-1\.5 -right-1\.5 -scale-y-100"
									style={{
										"border-image-source": "url(blp:hud_section-line)",
										"border-image-slice": "4 32 0 32 fill",
										"border-image-width": "auto",
									}}
								/>
							</div>
						</AgeSelectModelContext.Provider>
					</Show>
				</AudioContextProvider>
			</NestedTooltipContext.Provider>
		</>
	);
};

export const LegaciesUnlocksTab = ComponentRegistry.register({
	name: "LegaciesUnlocksTab",
	styles: [style],
	createInstance: LegaciesUnlocksTabComponent,
});
